glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
  in vec2 a_uv0;
  out vec2 v_uv0;
#endif
#if USE_FAKE3D
  varying vec3 camera_pos;
  varying vec2 offset;
  uniform Fake3D_vs {
    vec2 textureSize;
    float FOV;
    float y_rot;
    float x_rot;
  };
#endif
void main() {
  vec4 pos = vec4(a_position, 1);
  #if USE_FAKE3D
    vec2 UV = a_uv0;
    float sin_b = sin(y_rot / 180.0 * 3.14159265359);
    float cos_b = cos(y_rot / 180.0 * 3.14159265359);
    float sin_c = sin(x_rot / 180.0 * 3.14159265359);
    float cos_c = cos(x_rot / 180.0 * 3.14159265359);
    mat3 inv_rot_mat_y = mat3(
      vec3(cos_b, 0.0 , sin_b),
      vec3(0.0 , 1.0 , 0.0),
      vec3(-sin_b, 0.0 , cos_b)
    );
    mat3 inv_rot_mat_x = mat3(
      vec3(1.0 , 0.0 , 0.0),
      vec3(0.0 , cos_c , - sin_c),
      vec3(0.0 , sin_c , cos_c)
    );
    mat3 inv_rot_mat = inv_rot_mat_y * inv_rot_mat_x;
    float t = tan(FOV / 360.0 * 3.14159265359);
    float v = (0.5 / t) + 0.5;
    camera_pos = inv_rot_mat * vec3(UV - 0.5, 0.5 / t);
    camera_pos.xy *= inv_rot_mat[2].z * v;
    offset = inv_rot_mat[2].xy * v;
    pos.x += (UV.x - 0.5) * textureSize.x;
    pos.y -= (UV.y - 0.5) * textureSize.y;
  #endif
  #if CC_USE_MODEL
    pos = cc_matViewProj * cc_matWorld * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
    v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif
#if USE_FAKE3D
  varying vec3 camera_pos;
  varying vec2 offset;
  uniform Fake3D_fs {
    int cull_back;
  };
#endif
void main() {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  #if USE_FAKE3D
    if (cull_back != 0 && camera_pos.z <= 0.0)discard;
    vec2 uv = (camera_pos.xy / camera_pos.z).xy - offset;
    o = texture(texture, uv + 0.5);
    o.a *= step(max(abs(uv.x), abs(uv.y)), 0.5);
  #endif
  o *= v_color;
  gl_FragColor = o;
}

